      function WeddingTemplate(props) {
        var containerRef = React.useRef(null);

        React.useEffect(function() {
          function updateTimer() {
            var target = new Date("2026-11-25T14:00:00+03:00").getTime();
            var now = new Date().getTime();
            var diff = Math.max(0, target - now);

            var d = Math.floor(diff / (1000 * 60 * 60 * 24));
            var h = Math.floor((diff / (1000 * 60 * 60)) % 24);
            var m = Math.floor((diff / 1000 / 60) % 60);
            var s = Math.floor((diff / 1000) % 60);

            function plural(n, forms) {
              n = Math.abs(n) % 100;
              var n1 = n % 10;
              if (n > 10 && n < 20) return forms[2];
              if (n1 > 1 && n1 < 5) return forms[1];
              if (n1 === 1) return forms[0];
              return forms[2];
            }

            var dEl = document.getElementById("timerDays");
            var dwEl = document.getElementById("timerDaysWord");
            var hEl = document.getElementById("timerHours");
            var hwEl = document.getElementById("timerHoursWord");
            var mEl = document.getElementById("timerMinutes");
            var mwEl = document.getElementById("timerMinutesWord");
            var sEl = document.getElementById("timerSeconds");
            var swEl = document.getElementById("timerSecondsWord");

            if (dEl) dEl.textContent = String(d).padStart(2, "0");
            if (dwEl) dwEl.textContent = plural(d, ["день", "дня", "дней"]);
            if (hEl) hEl.textContent = String(h).padStart(2, "0");
            if (hwEl) hwEl.textContent = plural(h, ["час", "часа", "часов"]);
            if (mEl) mEl.textContent = String(m).padStart(2, "0");
            if (mwEl) mwEl.textContent = plural(m, ["минута", "минуты", "минут"]);
            if (sEl) sEl.textContent = String(s).padStart(2, "0");
            if (swEl) swEl.textContent = plural(s, ["секунда", "секунды", "секунд"]);
          }

          updateTimer();
          var timerInterval = setInterval(updateTimer, 1000);

          var form = document.getElementById("weddingForm");
          var handleFormSubmit = function(e) {
            e.preventDefault();
            var formData = {};
            var elements = form.elements;
            for (var i = 0; i < elements.length; i++) {
              var el = elements[i];
              if (!el.name) continue;
              if (el.type === "radio" || el.type === "checkbox") {
                if (el.checked) {
                  if (el.type === "checkbox") {
                    formData[el.name] = formData[el.name] ? (formData[el.name] + ", " + el.value) : el.value;
                  } else {
                    formData[el.name] = el.value;
                  }
                }
              } else {
                formData[el.name] = el.value;
              }
            }

            var btn = form.querySelector('button[type="submit"]') || form.querySelector('.btn') || form.querySelector('button');
            if (btn) btn.textContent = "Отправка...";

            fetch("/submit_form", {
              method: "POST",
              headers: { "Content-Type": "application/json" },
              body: JSON.stringify(formData)
            }).then(function(res) {
              if (btn) {
                btn.textContent = "Спасибо! Ответ отправлен";
                btn.style.setProperty("background-color", "#0c2610", "important");
                btn.disabled = true;
              }
            }).catch(function(err) {
              if (btn) {
                btn.textContent = "Ответ сохранен!";
                btn.disabled = true;
              }
            });
          };

          if (form) {
            form.addEventListener("submit", handleFormSubmit);
          }

          var styleId = "style-design-wedding-v12";
          if (!document.getElementById(styleId)) {
            var link = document.createElement("link");
            link.id = styleId;
            link.rel = "stylesheet";
            link.href = "/templates/design/wedding/v12/css/style.min.css";
            document.head.appendChild(link);
          }

                    // 1:1 Scroll Reveal Animations matching Eventrix v12
          if (typeof window !== "undefined" && window.__initEventrixAnimations) {
            window.__initEventrixAnimations();
          }

          return function() {
            clearInterval(timerInterval);
            if (form) {
              form.removeEventListener("submit", handleFormSubmit);
            }
          };
        }, []);

        return React.createElement("div", {
          className: "wrapper",
          ref: containerRef,
          dangerouslySetInnerHTML: { __html: '<main>' + htmlContent + '</main>' }
        });
      }

      WeddingTemplate.default = WeddingTemplate;
      exports.default = WeddingTemplate;
      module.exports = WeddingTemplate;
